#include <map>
#include <cassert>

// Called at the existing pre-edge capture point. Read only fields which the
// normal combo_master() already refreshed; never invoke extra DUT evaluation.
namespace wire_probe {
using U = unsigned long long;
struct Tx { U born, size, remaining, total; };
struct Snapshot { U cycles, ar, aw, r, w, b; };
struct Observer {
 std::vector<Snapshot> snapshots;
 U cycles=0, changed_cycles=0, read_occupied_cycles=0, write_occupied_cycles=0;
 U read_outstanding_sum=0, write_outstanding_sum=0, nr=0, nw=0, max_nr=0, max_nw=0;
 U ar=0,aw=0,w=0,r=0,b=0,ar_beats=0,aw_beats=0,ar_bytes=0,aw_bytes=0;
 U enabled_write_bytes=0,accepted_read_bytes=0,read_latency_sum=0,write_latency_sum=0;
 U first_read_latency_sum=0,max_read_latency=0,max_write_latency=0,read_completed=0;
 U both_data_fire=0, any_data_fire=0;
 U valids[5]={},stalls[5]={},strb_hist[65]={};
 std::map<U,U> ar_sizes,aw_sizes,ar_lens,aw_lens,ar_ids,aw_ids,read_latency,write_latency;
 std::map<U,std::deque<Tx>> reads,writes;
 static unsigned bucket(U n){return n?63-__builtin_clzll(n):0;}
 static void require(bool ok){if(!ok)std::abort();}
 void snapshot(){snapshots.push_back({cycles,ar,aw,r,w,b});}
 void note() {
  auto *d=g_rtl;
  ++cycles;
  changed_cycles += d->_chg != 0;
  read_occupied_cycles += nr != 0; write_occupied_cycles += nw != 0;
  read_outstanding_sum += nr; write_outstanding_sum += nw;
  bool v[5]={bool(d->io_m_axi_arvalid),bool(d->io_m_axi_awvalid),
    bool(d->io_m_axi_wvalid),bool(d->io_m_axi_rvalid),bool(d->io_m_axi_bvalid)};
  bool ready[5]={bool(d->io_m_axi_arready),bool(d->io_m_axi_awready),
    bool(d->io_m_axi_wready),bool(d->io_m_axi_rready),bool(d->io_m_axi_bready)};
  for(unsigned i=0;i<5;i++){valids[i]+=v[i];stalls[i]+=v[i]&&!ready[i];}
  both_data_fire += v[2]&&ready[2]&&v[3]&&ready[3];
  any_data_fire += (v[2]&&ready[2])||(v[3]&&ready[3]);
  // Retire old replies before a new request can reuse the same ID this edge.
  if(v[3]&&ready[3]) {
   ++r;auto &q=reads[d->io_m_axi_rid];require(!q.empty());auto &t=q.front();
   accepted_read_bytes+=t.size;
   if(t.remaining==t.total)first_read_latency_sum+=cycles-t.born;
   require(t.remaining>0);--t.remaining;
   require(bool(d->io_m_axi_rlast)==(t.remaining==0));
   if(!t.remaining){U age=cycles-t.born;read_latency_sum+=age;
    max_read_latency=std::max(max_read_latency,age);++read_latency[bucket(age)];
    ++read_completed;--nr;q.pop_front();}
  }
  if(v[4]&&ready[4]) {
   ++b;auto &q=writes[d->io_m_axi_bid];require(!q.empty());auto t=q.front();q.pop_front();
   U age=cycles-t.born;write_latency_sum+=age;max_write_latency=std::max(max_write_latency,age);
   ++write_latency[bucket(age)];--nw;
  }
  if(v[0]&&ready[0]) {
   ++ar;U size=U(1)<<d->io_m_axi_arsize,beats=U(d->io_m_axi_arlen)+1;
   require(size<=M_AXI_BYTES);require((d->io_m_axi_araddr&(M_AXI_BYTES-1))+size<=M_AXI_BYTES);
   ar_beats+=beats;ar_bytes+=beats*size;++ar_sizes[size];++ar_lens[beats];++ar_ids[d->io_m_axi_arid];
   reads[d->io_m_axi_arid].push_back({cycles,size,beats,beats});++nr;max_nr=std::max(max_nr,nr);
  }
  if(v[1]&&ready[1]) {
   ++aw;U size=U(1)<<d->io_m_axi_awsize,beats=U(d->io_m_axi_awlen)+1;
   require(size<=M_AXI_BYTES);aw_beats+=beats;aw_bytes+=size*beats;
   ++aw_sizes[size];++aw_lens[beats];++aw_ids[d->io_m_axi_awid];
   writes[d->io_m_axi_awid].push_back({cycles,size,beats,beats});++nw;max_nw=std::max(max_nw,nw);
  }
  if(v[2]&&ready[2]) {
   ++w;uint64_t mask=0;std::memcpy(&mask,&d->io_m_axi_wstrb,(M_AXI_BYTES+7)/8);
   auto n=__builtin_popcountll(mask);++strb_hist[n];enabled_write_bytes+=n;
  }
 }
 static void map(FILE*f,const char*name,const std::map<U,U>&values) {
  std::fprintf(f,",\"%s\":{",name);bool first=true;
  for(auto &p:values){std::fprintf(f,"%s\"%llu\":%llu",first?"":",",p.first,p.second);first=false;}
  std::fprintf(f,"}");
 }
 ~Observer() {
  const char*path=std::getenv("OPENGPU_WIRE_STATS");if(!path)return;
  require(g_rtl && cycles==g_rtl->_nt);
  FILE*f=std::fopen(path,"w");require(f);
  std::fprintf(f,"{\"cycles\":%llu,\"model_ticks_including_init\":%llu",cycles,U(g_rtl->_nt));
#define FIELD(x) std::fprintf(f,",\"" #x "\":%llu",x)
  FIELD(changed_cycles);FIELD(read_occupied_cycles);FIELD(write_occupied_cycles);
  FIELD(read_outstanding_sum);FIELD(write_outstanding_sum);FIELD(nr);FIELD(nw);FIELD(max_nr);FIELD(max_nw);
  FIELD(ar);FIELD(aw);FIELD(w);FIELD(r);FIELD(b);FIELD(ar_beats);FIELD(aw_beats);FIELD(ar_bytes);FIELD(aw_bytes);
  FIELD(enabled_write_bytes);FIELD(accepted_read_bytes);FIELD(read_latency_sum);FIELD(write_latency_sum);
  FIELD(first_read_latency_sum);FIELD(max_read_latency);FIELD(max_write_latency);FIELD(read_completed);
  FIELD(both_data_fire);FIELD(any_data_fire);
#undef FIELD
  const char*names[5]={"ar","aw","w","r","b"};
  for(unsigned i=0;i<5;i++)std::fprintf(f,",\"%s_valid_cycles\":%llu,\"%s_stall_cycles\":%llu",names[i],valids[i],names[i],stalls[i]);
  std::fprintf(f,",\"write_strobe_hist\":[");
  for(unsigned i=0;i<65;i++)std::fprintf(f,"%s%llu",i?",":"",strb_hist[i]);
  std::fprintf(f,"]");
  std::fprintf(f,",\"stats_snapshots\":[");
  for(unsigned i=0;i<snapshots.size();i++){auto x=snapshots[i];
   std::fprintf(f,"%s{\"cycles\":%llu,\"ar\":%llu,\"aw\":%llu,\"r\":%llu,\"w\":%llu,\"b\":%llu}",i?",":"",x.cycles,x.ar,x.aw,x.r,x.w,x.b);
  }
  std::fprintf(f,"]");
  map(f,"ar_size_hist",ar_sizes);map(f,"aw_size_hist",aw_sizes);
  map(f,"ar_beats_hist",ar_lens);map(f,"aw_beats_hist",aw_lens);
  map(f,"ar_id_hist",ar_ids);map(f,"aw_id_hist",aw_ids);
  map(f,"read_latency_log2_hist",read_latency);map(f,"write_latency_log2_hist",write_latency);
  std::fprintf(f,"}\n");std::fclose(f);
 }
} observer;
}

