import re

def generate(header):
    workers=sorted(set(re.findall(r'uint8_t (host_host_core_rp_parallelFrag_worker(?:_\d+)?)_texUnit_sampler_state;',header)))
    slots=sorted(set(map(int,re.findall(r'uint8_t host_host_core_rp_parallelFrag_texture_valid_(\d+);',header))))
    assert len(workers)==4 and slots==list(range(16))
    sampler=[];unit=[]
    for w in workers:
        p='g_rtl->'+w+'_texUnit_sampler_'
        sampler.append('{'+','.join(p+s for s in ['state','tapIssued','cacheLookupPending','cacheValid'])+',{'+','.join(p+'tapAddrs_'+str(i) for i in range(4))+'},{'+','.join(p+'cacheTags_'+str(i) for i in range(8))+'}}')
        unit.append('g_rtl->'+w+'_texUnit_state')
    p='g_rtl->host_host_core_rp_parallelFrag_texture_'
    valids=','.join(p+'valid_'+str(i) for i in slots)
    addresses=','.join(p+'addresses_'+str(i) for i in slots)
    owners=','.join(p+'owners_'+str(i) for i in slots)
    issued=','.join('g_rtl->'+w+'_texUnit_sampler_tapIssued' for w in workers)
    # Port observation uses registered addresses, masks and cache tags. The
    # next-state issued bits independently cross-check new owner allocations.
    source=r'''
namespace sampler_probe {
using U=unsigned long long;
