 for(unsigned i=0;i<16;i++){oldValid[i]=valid[i];oldAddress[i]=addr[i];oldOwner[i]=owner[i];pending+=bool(valid[i]);}
 any_pending+=pending!=0;pending_hist[pending]++;pending_sum+=pending;if(pending>peak_pending)peak_pending=pending;queue_occupied+=g_rtl->host_host_core_rp_parallelFrag_texture_request_maybe_full;
 for(unsigned w=0;w<4;w++){
  auto &s=v[w];if(s.state>=9||unit[w]>=11)std::abort();
  sampler_states[w][s.state]++;unit_states[w][unit[w]]++;cross_states[unit[w]][s.state]++;
  unit_sample_cycles+=unit[w]==9;fetch_worker_cycles+=s.state==5;
  req[w]=Request{};if(s.state!=5)continue;fetch++;
  unsigned mask=s.issued;if(s.pending){mask=0;for(unsigned a=0;a<4;a++)for(unsigned t=0;t<8;t++)if((s.valid&(1u<<t))&&s.addr[a]==s.tag[t]){mask|=1u<<a;break;}}
  for(unsigned a=0;a<4;a++){bool leader=true;for(unsigned b=0;b<a;b++)leader&=s.addr[a]!=s.addr[b];if(leader&&!(mask&(1u<<a))){req[w].valid=true;req[w].index=a;req[w].addr=s.addr[a];break;}}
  if(req[w].valid){requests++;for(unsigned i=0;i<16;i++)if(valid[i]&&addr[i]==req[w].addr)req[w].duplicate=true;}
 }
 any_fetch+=fetch!=0;fetch_no_request+=fetch!=0&&requests==0;fetch_waiting_replies+=fetch!=0&&requests==0&&pending!=0;request_pop[requests]++;request_workers+=requests;
}
