 for(unsigned w=0;w<4;w++)if(req[w].valid){if(issued[w]&(1u<<req[w].index)){accepted++;a++;per_worker_accept[w]++;}else{blocked_workers++;if(req[w].duplicate)duplicate_blocked++;else{bool full=true;for(unsigned i=0;i<16;i++)full&=oldValid[i];if(full)capacity_blocked++;else other_blocked++;}}}
 for(unsigned i=0;i<16;i++){
  if(!oldValid[i]&&valid[i]){allocated++;b++;birth[i]=ticks;unsigned w=owner[i];if(w>=4||!req[w].valid||req[w].addr!=addr[i]||!(issued[w]&(1u<<req[w].index)))std::abort();}
  if(oldValid[i]&&!valid[i]){retired++;c++;U age=ticks-birth[i];latency_sum+=age;if(age>max_latency)max_latency=age;unsigned bucket=age<=2?0:age<=4?1:age<=8?2:age<=16?3:age<=32?4:age<=64?5:age<=128?6:7;latency[bucket]++;}
 }
