}
static void array(FILE*f,const char*name,const U*p,unsigned n){std::fprintf(f,",\"%s\":[",name);for(unsigned i=0;i<n;i++)std::fprintf(f,"%s%llu",i?",":"",p[i]);std::fprintf(f,"]");}
struct Reporter{~Reporter(){
 const char*path=std::getenv("OPENGPU_SAMPLER_STATS");if(!path)return;
 if(!g_rtl||ticks!=g_rtl->_nt)std::abort();FILE*f=std::fopen(path,"w");if(!f)std::abort();
 std::fprintf(f,"{\"ticks\":%llu",ticks);
