 for(unsigned i=0;i<4;i++){char name[64];std::snprintf(name,64,"worker%u_sampler_states",i);array(f,name,sampler_states[i],9);std::snprintf(name,64,"worker%u_unit_states",i);array(f,name,unit_states[i],11);}
 for(unsigned i=0;i<11;i++){char name[64];std::snprintf(name,64,"unit_state%u_sampler_states",i);array(f,name,cross_states[i],9);}
 std::fprintf(f,"}\n");std::fclose(f);
