'''
    return source.replace('@SAMPLERS@',','.join(sampler)).replace('@VALIDS@',valids).replace('@ADDRESSES@',addresses).replace('@OWNERS@',owners).replace('@ISSUED@',issued).replace('@UNITS@',','.join(unit))
